package com.parvezit.businessmanager;

import android.app.*;
import android.os.Bundle;
import android.graphics.*;
import android.graphics.pdf.PdfDocument;
import android.print.*;
import android.view.*;
import android.widget.*;
import android.database.Cursor;
import android.content.*;
import android.net.Uri;
import androidx.core.content.FileProvider;
import java.text.DecimalFormat;
import java.io.*;

public class MainActivity extends Activity {
 DB db;LinearLayout root,body;DecimalFormat money=new DecimalFormat("#,##0.00");int navy=Color.rgb(20,39,66),teal=Color.rgb(0,130,125);static final int BACKUP=101,RESTORE=102;
 public void onCreate(Bundle b){super.onCreate(b);db=new DB(this);showHome();}
 TextView txt(String s,int z,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(Color.rgb(30,40,50));if(bold)t.setTypeface(null,1);t.setPadding(4,8,4,8);return t;}
 Button btn(String s){Button b=new Button(this);b.setText(s);b.setAllCaps(false);return b;}
 EditText field(String s,int type){EditText e=new EditText(this);e.setHint(s);e.setInputType(type);return e;}
 void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
 void start(String title){root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(0xfff6f8fb);TextView h=txt("Parvez iT  |  "+title,19,true);h.setTextColor(-1);h.setBackgroundColor(navy);h.setPadding(16,18,8,18);root.addView(h);body=new LinearLayout(this);body.setPadding(14,10,14,14);body.setOrientation(1);ScrollView sc=new ScrollView(this);sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));LinearLayout nav=new LinearLayout(this);String[] n={"হোম","পণ্য","কাস্টমার","ইনভয়েস","রিপোর্ট"};for(int i=0;i<n.length;i++){final int x=i;Button b=btn(n[i]);b.setTextSize(10);b.setOnClickListener(v->{if(x==0)showHome();if(x==1)showProducts();if(x==2)showCustomers();if(x==3)invoiceForm();if(x==4)reports();});nav.addView(b,new LinearLayout.LayoutParams(0,-2,1));}root.addView(nav);setContentView(root);}
 void card(String a,String b){LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(12,8,12,8);l.setBackgroundColor(-1);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=7;body.addView(l,p);l.addView(txt(a,13,false));TextView v=txt(b,21,true);v.setTextColor(teal);l.addView(v);}
 void action(String s,Runnable r){Button b=btn(s);b.setOnClickListener(v->r.run());body.addView(b);}
 void showHome(){start("ড্যাশবোর্ড");double in=db.total("IN"),out=db.total("OUT");body.addView(txt("Smart Solutions for Smarter Work.",14,false));card("মোট আয় / বিক্রি","৳ "+money.format(in));card("মোট খরচ","৳ "+money.format(out));card("নিট পার্থক্য","৳ "+money.format(in-out));action("+ নতুন আয়",()->transactionForm("IN"));action("+ নতুন খরচ",()->transactionForm("OUT"));action("+ পণ্য যোগ",()->productForm());action("+ ইনভয়েস তৈরি",()->invoiceForm());action("+ বাকি টাকা আদায়",()->collectForm());action("+ পণ্য ক্রয় / স্টক বাড়ান",()->purchaseForm());action("সাপ্লায়ার যোগ / তালিকা",()->supplierForm());action("ডেটা ব্যাকআপ নিন",()->backup());action("ব্যাকআপ রিস্টোর",()->restore());body.addView(txt("সাম্প্রতিক লেনদেন",17,true));Cursor c=db.recent();while(c.moveToNext())body.addView(txt((c.getString(1).equals("IN")?"আয় + ":"খরচ - ")+c.getString(2)+" | ৳"+money.format(c.getDouble(3)),13,false));c.close();}
 void transactionForm(String type){start(type.equals("IN")?"নতুন আয়":"নতুন খরচ");EditText n=field("বিবরণ",1),a=field("টাকার পরিমাণ",8194),note=field("নোট",1);body.addView(n);body.addView(a);body.addView(note);action("সংরক্ষণ",()->{try{db.addTransaction(type,n.getText().toString(),Double.parseDouble(a.getText().toString()),note.getText().toString());showHome();}catch(Exception e){toast("সঠিক তথ্য দিন");}});}
 void showProducts(){start("পণ্য ও স্টক");action("+ পণ্য যোগ",()->productForm());Cursor c=db.products();while(c.moveToNext())body.addView(txt(c.getString(1)+" | "+c.getString(2)+" | স্টক "+c.getInt(3)+" | ক্রয় ৳"+money.format(c.getDouble(4))+" | বিক্রয় ৳"+money.format(c.getDouble(5)),13,false));c.close();}
 void productForm(){start("নতুন পণ্য");EditText n=field("পণ্যের নাম",1),cat=field("ক্যাটাগরি",1),q=field("প্রাথমিক স্টক",2),buy=field("ক্রয়মূল্য",8194),sell=field("বিক্রয়মূল্য",8194);for(EditText e:new EditText[]{n,cat,q,buy,sell})body.addView(e);action("সংরক্ষণ",()->{try{db.addProduct(n.getText().toString(),cat.getText().toString(),Integer.parseInt(q.getText().toString()),Double.parseDouble(buy.getText().toString()),Double.parseDouble(sell.getText().toString()));showProducts();}catch(Exception e){toast("সব তথ্য সঠিকভাবে দিন");}});}
 void showCustomers(){start("কাস্টমার ও বকেয়া");action("+ কাস্টমার যোগ",()->customerForm());action("বাকি টাকা আদায়",()->collectForm());Cursor c=db.customers();while(c.moveToNext())body.addView(txt(c.getString(0)+" | "+c.getString(1)+" | বকেয়া ৳"+money.format(c.getDouble(2)),14,false));c.close();}
 void customerForm(){start("কাস্টমার যোগ");EditText n=field("নাম",1),p=field("ফোন",3);body.addView(n);body.addView(p);action("সংরক্ষণ",()->{if(db.addCustomer(n.getText().toString(),p.getText().toString(),0))showCustomers();else toast("কাস্টমার যোগ হয়নি");});}
 void supplierForm(){start("সাপ্লায়ার");EditText n=field("সাপ্লায়ারের নাম",1),p=field("ফোন",3);body.addView(n);body.addView(p);action("সাপ্লায়ার সংরক্ষণ",()->{if(db.addSupplier(n.getText().toString(),p.getText().toString()))toast("সাপ্লায়ার সংরক্ষিত");else toast("সংরক্ষণ হয়নি");});Cursor c=db.suppliers();while(c.moveToNext())body.addView(txt(c.getString(0)+" | "+c.getString(1)+" | বকেয়া ৳"+money.format(c.getDouble(2)),13,false));c.close();}
 void invoiceForm(){start("ইনভয়েস");EditText customer=field("কাস্টমারের নাম",1),phone=field("মোবাইল",3),qty=field("পরিমাণ",2),paid=field("এখন জমা (না দিলে 0)",8194);Spinner sp=new Spinner(this);java.util.ArrayList<String> labels=new java.util.ArrayList<>();java.util.ArrayList<Integer> ids=new java.util.ArrayList<>();java.util.ArrayList<Double> prices=new java.util.ArrayList<>();Cursor c=db.products();while(c.moveToNext()){labels.add(c.getString(1)+" (স্টক "+c.getInt(3)+") - ৳"+money.format(c.getDouble(5)));ids.add(c.getInt(0));prices.add(c.getDouble(5));}c.close();if(labels.isEmpty()){body.addView(txt("আগে পণ্য যোগ করুন",15,true));return;}sp.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,labels));body.addView(customer);body.addView(phone);body.addView(sp);body.addView(qty);body.addView(paid);action("ইনভয়েস তৈরি ও স্টক কমান",()->{try{int x=sp.getSelectedItemPosition(),q=Integer.parseInt(qty.getText().toString());double p=paid.length()==0?0:Double.parseDouble(paid.getText().toString());String pn=labels.get(x).split(" \\\\(স্টক")[0];long id=db.createInvoice(customer.getText().toString(),phone.getText().toString(),ids.get(x),pn,q,prices.get(x),p);if(id<0){toast("স্টক কম অথবা জমার টাকা মোটের বেশি");return;}invoiceActions(id);}catch(Exception e){toast("তথ্য সঠিকভাবে দিন");}});}
 String invoiceText(long id){Cursor c=db.invoice(id);String s="";if(c.moveToFirst()){double due=c.getDouble(3)-c.getDouble(9);s="Parvez iT\\nSmart Solutions for Smarter Work.\\nSamabay New Market, 4th Floor, Shop #24, Chashara, Narayanganj, Dhaka, Bangladesh\\nPhone: 01922776995 | Email: info.parvezit@gmail.com\\n\\nINVOICE #"+c.getLong(0)+"\\nDate: "+c.getString(4)+"\\nCustomer: "+c.getString(1)+"\\nPhone: "+c.getString(2)+"\\n\\nItem: "+c.getString(5)+"\\nQty: "+c.getInt(6)+"\\nUnit price: BDT "+money.format(c.getDouble(7))+"\\nTotal: BDT "+money.format(c.getDouble(3))+"\\nPaid: BDT "+money.format(c.getDouble(9))+"\\nDue: BDT "+money.format(due)+"\\n\\nThank you for your business!";}c.close();return s;}
 void invoiceActions(long id){start("ইনভয়েস #"+id);body.addView(txt(invoiceText(id).replace("\\n","\n"),15,false));action("PDF তৈরি / শেয়ার",()->makePdf(id));action("প্রিন্ট / Save as PDF",()->printInvoice(id));action("হোম",()->showHome());}
 void drawPdf(PdfDocument doc,long id){PdfDocument.Page pg=doc.startPage(new PdfDocument.PageInfo.Builder(595,842,1).create());Canvas cv=pg.getCanvas();Paint p=new Paint(3);int y=55;p.setTextSize(22);p.setTypeface(Typeface.create("sans-serif",Typeface.BOLD));cv.drawText("Parvez iT",40,y,p);p.setTextSize(10);p.setTypeface(Typeface.DEFAULT);y+=24;for(String line:invoiceText(id).split("\\\\n")){cv.drawText(line,40,y,p);y+=22;}doc.finishPage(pg);}
 void makePdf(long id){try{PdfDocument d=new PdfDocument();drawPdf(d,id);File f=new File(getCacheDir(),"ParvezIT_Invoice_"+id+".pdf");FileOutputStream o=new FileOutputStream(f);d.writeTo(o);o.close();d.close();Uri u=FileProvider.getUriForFile(this,getPackageName()+".provider",f);Intent s=new Intent(Intent.ACTION_SEND);s.setType("application/pdf");s.putExtra(Intent.EXTRA_STREAM,u);s.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(s,"PDF শেয়ার করুন"));}catch(Exception e){toast("PDF তৈরি হয়নি: "+e.getMessage());}}
 void printInvoice(long id){PrintManager pm=(PrintManager)getSystemService(PRINT_SERVICE);String content=invoiceText(id);pm.print("ParvezIT_Invoice_"+id,new PrintDocumentAdapter(){
 public void onLayout(PrintAttributes a,PrintAttributes b,android.os.CancellationSignal c,LayoutResultCallback cb,Bundle x){cb.onLayoutFinished(new PrintDocumentInfo.Builder("invoice.pdf").setContentType(PrintDocumentInfo.CONTENT_TYPE_DOCUMENT).setPageCount(1).build(),true);}
 public void onWrite(PageRange[] pages,android.os.ParcelFileDescriptor dest,android.os.CancellationSignal c,WriteResultCallback cb){try{PdfDocument d=new PdfDocument();PdfDocument.Page pg=d.startPage(new PdfDocument.PageInfo.Builder(595,842,1).create());Paint p=new Paint(3);p.setTextSize(13);int y=55;for(String line:content.split("\\\\n")){pg.getCanvas().drawText(line,35,y,p);y+=23;}d.finishPage(pg);d.writeTo(new FileOutputStream(dest.getFileDescriptor()));d.close();cb.onWriteFinished(new PageRange[]{PageRange.ALL_PAGES});}catch(Exception e){cb.onWriteFailed(e.toString());}}
 },new PrintAttributes.Builder().setMediaSize(PrintAttributes.MediaSize.ISO_A4).setResolution(new PrintAttributes.Resolution("default","default",300,300)).setMinMargins(PrintAttributes.Margins.NO_MARGINS).build());}
 void collectForm(){start("বাকি টাকা আদায়");java.util.ArrayList<String> names=new java.util.ArrayList<>();Cursor c=db.customers();while(c.moveToNext())if(c.getDouble(2)>0)names.add(c.getString(0)+" (বাকি ৳"+money.format(c.getDouble(2))+")");c.close();if(names.isEmpty()){body.addView(txt("কোনো বকেয়া নেই",14,false));return;}Spinner sp=new Spinner(this);sp.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,names));EditText amount=field("আদায়ের পরিমাণ",8194),note=field("নোট",1);body.addView(sp);body.addView(amount);body.addView(note);action("আদায় সংরক্ষণ",()->{try{String name=names.get(sp.getSelectedItemPosition()).split(" \\\\(বাকি")[0];if(db.collectDue(name,Double.parseDouble(amount.getText().toString()),note.getText().toString())){toast("টাকা আদায় সংরক্ষিত");showCustomers();}else toast("পরিমাণ বকেয়ার চেয়ে বেশি বা ভুল");}catch(Exception e){toast("সঠিক পরিমাণ দিন");}});}
 void purchaseForm(){start("পণ্য ক্রয় / স্টক বাড়ান");EditText supplier=field("সাপ্লায়ারের নাম",1),qty=field("পরিমাণ",2),cost=field("প্রতি পিস ক্রয়মূল্য",8194);Spinner sp=new Spinner(this);java.util.ArrayList<String> names=new java.util.ArrayList<>();java.util.ArrayList<Integer> ids=new java.util.ArrayList<>();Cursor c=db.products();while(c.moveToNext()){names.add(c.getString(1));ids.add(c.getInt(0));}c.close();if(names.isEmpty()){body.addView(txt("আগে পণ্য যোগ করুন",14,false));return;}sp.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,names));body.addView(supplier);body.addView(sp);body.addView(qty);body.addView(cost);action("ক্রয় সংরক্ষণ ও স্টক বাড়ান",()->{try{int x=sp.getSelectedItemPosition();if(db.addPurchase(supplier.getText().toString(),ids.get(x),names.get(x),Integer.parseInt(qty.getText().toString()),Double.parseDouble(cost.getText().toString()))){toast("ক্রয় ও স্টক আপডেট হয়েছে");showProducts();}else toast("ক্রয় সংরক্ষণ হয়নি");}catch(Exception e){toast("সঠিক তথ্য দিন");}});}
 void reports(){start("লাভ-ক্ষতি রিপোর্ট");double in=db.total("IN"),out=db.total("OUT");card("মোট আয় / বিক্রি","৳ "+money.format(in));card("মোট খরচ / ক্রয়","৳ "+money.format(out));card("নিট ক্যাশ পার্থক্য","৳ "+money.format(in-out));card("মোট কাস্টমার বকেয়া","৳ "+money.format(db.sum("SELECT COALESCE(SUM(due),0) FROM customers")));card("মোট স্টকের ক্রয়মূল্য","৳ "+money.format(db.sum("SELECT COALESCE(SUM(qty*buy),0) FROM products")));body.addView(txt("নোট: এই রিপোর্টটি মোট লেনদেনভিত্তিক ক্যাশ রিপোর্ট; এটি পূর্ণ অ্যাকাউন্টিং লাভের হিসাব নয়।",12,false));}
 void backup(){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/octet-stream");i.putExtra(Intent.EXTRA_TITLE,"ParvezIT_Backup.db");startActivityForResult(i,101);}
 void restore(){new AlertDialog.Builder(this).setTitle("ব্যাকআপ রিস্টোর").setMessage("বর্তমান ডেটা নির্বাচিত ব্যাকআপ দিয়ে প্রতিস্থাপিত হবে। আগে বর্তমান ডেটার ব্যাকআপ নিন।").setNegativeButton("বাতিল",null).setPositiveButton("ফাইল নির্বাচন",(d,w)->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");startActivityForResult(i,102);}).show();}
 protected void onActivityResult(int r,int res,Intent data){super.onActivityResult(r,res,data);if(res!=RESULT_OK||data==null)return;try{Uri u=data.getData();if(r==101){try(InputStream in=new FileInputStream(getDatabasePath("parvezit.db"));OutputStream out=getContentResolver().openOutputStream(u)){byte[] b=new byte[8192];int n;while((n=in.read(b))>0)out.write(b,n);}toast("ব্যাকআপ সংরক্ষিত");}else if(r==102){db.close();try(InputStream in=getContentResolver().openInputStream(u);OutputStream out=new FileOutputStream(getDatabasePath("parvezit.db"))){byte[] b=new byte[8192];int n;while((n=in.read(b))>0)out.write(b,n);}db=new DB(this);showHome();toast("ব্যাকআপ রিস্টোর হয়েছে");}}catch(Exception e){toast("কাজটি হয়নি: "+e.getMessage());}}
}